(function(){
  if (typeof AutoJS === 'undefined') { throw new Error('端点: server 侧 AutoJS 全局缺失'); }
  AutoJS.command('kill @e[type=astral_dice:sykestentacle]');
  AutoJS.command('kill @e[type=!player,distance=..48]');
  AutoJS.command('effect clear @a');
  AutoJS.command('clear @a');
  AutoJS.command('execute at @a run summon astral_dice:sykestentacle ~ ~1 ~');
  var BIR = Java.loadClass('net.minecraft.core.registries.BuiltInRegistries');
  var it = AutoJS.level().getAllEntities().iterator();
  var out = { found: false };
  while (it.hasNext()) {
    var e = it.next();
    if (String(BIR.ENTITY_TYPE.getKey(e.getType())) !== 'astral_dice:sykestentacle') { continue; }
    out.found = true;
    out.entityId = Number(e.getId());
    out.maxHealth = Number(e.getMaxHealth());
    out.health = Number(e.getHealth());
    break;
  }
  return out;
})()

