(function(){
  var mc = Java.loadClass('net.minecraft.client.Minecraft').getInstance();
  if (mc.level === null) { return false; }
  var BIR = Java.loadClass('net.minecraft.core.registries.BuiltInRegistries');
  var it = mc.level.entitiesForRendering().iterator();
  while (it.hasNext()) {
    var e = it.next();
    if (String(BIR.ENTITY_TYPE.getKey(e.getType())) !== 'astral_dice:sykestentacle') { continue; }
    var c = e.getAnimatableInstanceCache().getManagerForId(Number(e.getId())).getAnimationControllers();
    var ci = c.get('idle');
    return ci !== null && String(ci.getAnimationState()) === 'RUNNING';
  }
  return false;
})()

(function(){
  var mc = Java.loadClass('net.minecraft.client.Minecraft').getInstance();
  if (mc.level === null) { throw new Error('端点: client 未进入世界'); }
  var BIR = Java.loadClass('net.minecraft.core.registries.BuiltInRegistries');
  var it = mc.level.entitiesForRendering().iterator();
  var out = { found: false, idleState: 'none', actionState: 'none', idleAnim: '', actionAnim: '' };
  while (it.hasNext()) {
    var e = it.next();
    if (String(BIR.ENTITY_TYPE.getKey(e.getType())) !== 'astral_dice:sykestentacle') { continue; }
    out.found = true;
    out.entityId = Number(e.getId());
    var c = e.getAnimatableInstanceCache().getManagerForId(Number(e.getId())).getAnimationControllers();
    var i1 = c.get('idle'), i2 = c.get('action');
    out.idleState = i1 === null ? 'none' : String(i1.getAnimationState());
    out.actionState = i2 === null ? 'none' : String(i2.getAnimationState());
    out.idleAnim = i1 === null ? '' : String(i1.getCurrentAnimation());
    out.actionAnim = i2 === null ? '' : String(i2.getCurrentAnimation());
    break;
  }
  return out;
})()

(function(){
  var BIR = Java.loadClass('net.minecraft.core.registries.BuiltInRegistries');
  var it = AutoJS.level().getAllEntities().iterator();
  var e = null;
  while (it.hasNext()) {
    var x = it.next();
    if (String(BIR.ENTITY_TYPE.getKey(x.getType())) === 'astral_dice:sykestentacle') { e = x; break; }
  }
  if (e === null) { throw new Error('未找到触手实体'); }
  var out = { found: true, entityId: Number(e.getId()), maxHealth: Number(e.getMaxHealth()) };
  out.hpBefore = Number(e.getHealth());
  AutoJS.command('damage @e[type=astral_dice:sykestentacle,limit=1] 4 minecraft:player_attack');
  out.hpAfter = Number(e.getHealth());
  out.delta = out.hpBefore - out.hpAfter;
  out.aliveAfter = !e.isRemoved();
  return out;
})()

